ALTER TYPE public.payment_provider ADD VALUE IF NOT EXISTS 'paystack';
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS request_key uuid UNIQUE;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS payment_reference text UNIQUE;
ALTER TABLE public.payment_intents ADD COLUMN IF NOT EXISTS order_id uuid REFERENCES public.orders(id);
CREATE TABLE public.cart_items(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,quantity integer NOT NULL DEFAULT 1 CHECK(quantity BETWEEN 1 AND 20),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,product_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cart_items TO authenticated; GRANT ALL ON public.cart_items TO service_role; ALTER TABLE public.cart_items ENABLE ROW LEVEL SECURITY; CREATE POLICY cart_owner ON public.cart_items FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.wishlist_items(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,product_id));
GRANT SELECT,INSERT,DELETE ON public.wishlist_items TO authenticated; GRANT ALL ON public.wishlist_items TO service_role; ALTER TABLE public.wishlist_items ENABLE ROW LEVEL SECURITY; CREATE POLICY wishlist_owner ON public.wishlist_items FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.recently_viewed(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,viewed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,product_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.recently_viewed TO authenticated; GRANT ALL ON public.recently_viewed TO service_role; ALTER TABLE public.recently_viewed ENABLE ROW LEVEL SECURITY; CREATE POLICY viewed_owner ON public.recently_viewed FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE INDEX viewed_user_time ON public.recently_viewed(user_id,viewed_at DESC);
CREATE FUNCTION public.prepare_cart_order(_user uuid,_request uuid,_external boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ord uuid; w public.wallets; r record; total numeric:=0; ids uuid[]; tx uuid; ref text; BEGIN SELECT id INTO ord FROM public.orders WHERE request_key=_request AND user_id=_user; IF FOUND THEN RETURN ord; END IF; IF EXISTS(SELECT 1 FROM public.profiles WHERE id=_user AND suspended) THEN RAISE EXCEPTION 'Account suspended'; END IF; SELECT * INTO w FROM public.wallets WHERE user_id=_user FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Wallet not found'; END IF; SELECT id INTO ord FROM public.orders WHERE request_key=_request AND user_id=_user; IF FOUND THEN RETURN ord; END IF; IF NOT EXISTS(SELECT 1 FROM public.cart_items WHERE user_id=_user) THEN RAISE EXCEPTION 'Your cart is empty'; END IF; FOR r IN SELECT p.id,p.title,p.price,p.stock,p.published,p.currency,c.quantity FROM public.cart_items c JOIN public.products p ON p.id=c.product_id WHERE c.user_id=_user ORDER BY p.id FOR UPDATE OF p,c LOOP IF NOT r.published OR r.currency<>'NGN' OR r.stock<r.quantity OR r.quantity NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'An item is unavailable or exceeds stock'; END IF; total:=total+r.price*r.quantity; END LOOP; IF total<=0 THEN RAISE EXCEPTION 'Invalid order total'; END IF; IF NOT _external AND w.balance<total THEN RAISE EXCEPTION 'Insufficient wallet balance'; END IF; ref:='bp-'||_request::text; INSERT INTO public.orders(user_id,total,currency,status,request_key,payment_reference) VALUES(_user,total,'NGN','pending',_request,ref) RETURNING id INTO ord; FOR r IN SELECT p.*,c.quantity FROM public.cart_items c JOIN public.products p ON p.id=c.product_id WHERE c.user_id=_user ORDER BY p.id LOOP SELECT array_agg(t.id) INTO ids FROM(SELECT id FROM public.product_credentials WHERE product_id=r.id AND order_id IS NULL ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT r.quantity)t; IF COALESCE(cardinality(ids),0)<r.quantity THEN RAISE EXCEPTION 'An item has insufficient deliverable inventory'; END IF; UPDATE public.product_credentials SET order_id=ord WHERE id=ANY(ids); UPDATE public.products SET stock=stock-r.quantity,updated_at=now() WHERE id=r.id; INSERT INTO public.order_items(order_id,product_id,title,unit_price,quantity) VALUES(ord,r.id,r.title,r.price,r.quantity); END LOOP; IF NOT _external THEN UPDATE public.wallets SET balance=balance-total,updated_at=now() WHERE id=w.id RETURNING balance INTO w.balance; INSERT INTO public.wallet_transactions(wallet_id,user_id,type,amount,balance_after,provider,reference,description) VALUES(w.id,_user,'debit',total,w.balance,'manual',ref,'Cart purchase') RETURNING id INTO tx; UPDATE public.orders SET status='completed',wallet_tx_id=tx WHERE id=ord; UPDATE public.product_credentials SET assigned_to=_user,delivered_at=now() WHERE order_id=ord; UPDATE public.order_items i SET delivered_payload=(SELECT string_agg(c.content,E'\n---\n' ORDER BY c.created_at) FROM public.product_credentials c WHERE c.order_id=ord AND c.product_id=i.product_id) WHERE i.order_id=ord; DELETE FROM public.cart_items WHERE user_id=_user AND product_id IN(SELECT product_id FROM public.order_items WHERE order_id=ord); END IF; RETURN ord; END $$;
REVOKE ALL ON FUNCTION public.prepare_cart_order(uuid,uuid,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.prepare_cart_order(uuid,uuid,boolean) TO service_role;
CREATE FUNCTION public.purchase_cart(_request uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; RETURN public.prepare_cart_order(auth.uid(),_request,false); END $$; REVOKE ALL ON FUNCTION public.purchase_cart(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.purchase_cart(uuid) TO authenticated;
CREATE FUNCTION public.settle_paystack(_reference text,_amount numeric,_currency text,_provider_id text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.payment_intents; w public.wallets; b numeric; BEGIN SELECT * INTO i FROM public.payment_intents WHERE reference=_reference AND provider::text='paystack' FOR UPDATE; IF NOT FOUND OR i.amount<>_amount OR i.currency<>_currency THEN RAISE EXCEPTION 'Payment mismatch'; END IF; IF i.status='success' THEN RETURN i.order_id; END IF; IF i.status<>'pending' THEN RAISE EXCEPTION 'Payment is not pending'; END IF; IF i.order_id IS NULL THEN SELECT * INTO w FROM public.wallets WHERE user_id=i.user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Wallet missing'; END IF; UPDATE public.wallets SET balance=balance+_amount,updated_at=now() WHERE id=w.id RETURNING balance INTO b; INSERT INTO public.wallet_transactions(wallet_id,user_id,type,amount,balance_after,provider,reference,description) VALUES(w.id,i.user_id,'credit',_amount,b,'paystack',_reference,'Wallet funded via PayStark (Paystack)'); ELSE UPDATE public.orders SET status='completed' WHERE id=i.order_id AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'Order no longer pending'; END IF; UPDATE public.product_credentials SET assigned_to=i.user_id,delivered_at=now() WHERE order_id=i.order_id; UPDATE public.order_items oi SET delivered_payload=(SELECT string_agg(c.content,E'\n---\n' ORDER BY c.created_at) FROM public.product_credentials c WHERE c.order_id=i.order_id AND c.product_id=oi.product_id) WHERE oi.order_id=i.order_id; DELETE FROM public.cart_items WHERE user_id=i.user_id AND product_id IN(SELECT product_id FROM public.order_items WHERE order_id=i.order_id); END IF; UPDATE public.payment_intents SET status='success',provider_reference=_provider_id,updated_at=now() WHERE id=i.id; RETURN i.order_id; END $$; REVOKE ALL ON FUNCTION public.settle_paystack(text,numeric,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.settle_paystack(text,numeric,text,text) TO service_role;
CREATE FUNCTION public.fail_paystack(_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.payment_intents; BEGIN SELECT * INTO i FROM public.payment_intents WHERE reference=_reference AND provider::text='paystack' FOR UPDATE; IF NOT FOUND OR i.status<>'pending' THEN RETURN; END IF; IF i.order_id IS NOT NULL THEN UPDATE public.products p SET stock=p.stock+oi.quantity FROM public.order_items oi WHERE oi.order_id=i.order_id AND oi.product_id=p.id; UPDATE public.product_credentials SET order_id=NULL WHERE order_id=i.order_id AND assigned_to IS NULL; UPDATE public.orders SET status='failed' WHERE id=i.order_id AND status='pending'; END IF; UPDATE public.payment_intents SET status='failed',updated_at=now() WHERE id=i.id; END $$; REVOKE ALL ON FUNCTION public.fail_paystack(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.fail_paystack(text) TO service_role;